local N=nil local S=nil local C=game:GetService("Players")local n=game:GetService("StarterGui")local Z=C.LocalPlayer local V="zaml/characters"local function B(N)pcall(function()n:SetCore("SendNotification",{Title="Save Character";Text=N;Duration=6})end)end local function g(N)error(N,0)end local function E()if type(saveinstance)~="function"then g("this executor has no saveinstance")end local n=Z if N~=nil then n=nil local S=(tostring(N)):lower()for N,C in ipairs(C:GetPlayers())do if C.Name:lower()==S or C.DisplayName:lower()==S then n=C break end end if not n then g("no player named \'"..(tostring(N).."\' in this server"))end end local B=n.Character if not B then g(n.Name.." has no character right now")end local function E()local N=0 pcall(function()for S,C in ipairs(listfiles(V))do local n=tonumber((C:match("([^/\\]+)$")or""):match("^(%d+)%.rbxmx?$"))if n and n>N then N=n end end end)return N+1 end if isfolder and makefolder then if not isfolder("zaml")then makefolder("zaml")end if not isfolder(V)then makefolder(V)end end local Y=S~=nil and(tostring(S)):gsub("[^%w%-_ ]","_")or tostring(E())if Y==""then Y=tostring(E())end local k=B.Archivable B.Archivable=true for N,S in ipairs(B:GetDescendants())do pcall(function()S.Archivable=true end)end local b=B:Clone()B.Archivable=k if not b then g("the character could not be cloned")end for N,S in ipairs(b:GetDescendants())do if S:IsA("LuaSourceContainer")or S:IsA("Sound")or S:IsA("ForceField")or S:IsA("BillboardGui")then S:Destroy()elseif S:IsA("BasePart")then S.Anchored=true end end b.Name=Y local O,R=0,0 for N,S in ipairs(b:GetDescendants())do if S:IsA("BasePart")then O=O+1 end if S:IsA("Accessory")then R=R+1 end end if isfolder and makefolder then if not isfolder("zaml")then makefolder("zaml")end if not isfolder(V)then makefolder(V)end end local H="zaml"..tostring(math.random(100000,999999))local c,y=pcall(saveinstance,b,{FileName=H,mode="model"})if not c then g("saveinstance failed: "..tostring(y))end local P local X=os.clock()+30 while os.clock()<X and not P do for N,S in ipairs({".rbxmx";".rbxm"})do if isfile(H..S)then P=H..S end end if not P then task.wait(.25)end end if not P then g("saveinstance ran but no file appeared within 30 s")end local G,p=-1,0 while p<3 do local N,S=pcall(readfile,P)local C=N and#S or-1 if C==G and C>0 then p=p+1 else p=0 end G=C task.wait(.2)end local t=P:match("%.%w+$")local d=V..("/"..(Y..t))writefile(d,readfile(P))pcall(delfile,P)b:Destroy()return Y..t end local Y,k=pcall(E)if Y then B("Saved "..k)else B("Failed to save character")end
